import{_ as e,c as r,o as t,a4 as n}from"./chunks/framework.BU14wsQo.js";const o="/ai/daily/2026-06-26/news_01kvzqp8j9e8hsx48em43cyztm.avif",i="/ai/daily/2026-06-26/news_01kvzqpe92e8hsx48g66snfrz7.avif",l="/ai/daily/2026-06-26/news_01kvzqpgh3e8hsx48v5nt95bck.avif",s="/ai/daily/2026-06-26/news_01kvzqpjxpe8hsx4927tkgnd6w.avif",h="/ai/daily/2026-06-26/news_01kvzqpnk4e8hsx498vvws045c.avif",c="/ai/daily/2026-06-26/news_01kvzqpre4e8hsx49nffzwjfrk.avif",A=JSON.parse('{"title":"AI大事件 2026/6/26","description":"AI大事件 2026/6/26 - 陈老板的百宝箱 AI 大事件日报，追踪模型发布、AI 产品、前沿研究、开源工具、安全政策与行业动态。","frontmatter":{"linkTitle":"06-26 AI大事件","title":"AI大事件 2026/6/26","weight":6,"breadcrumbs":false,"comments":true,"description":""},"headers":[],"relativePath":"ai/daily/cn/2026-06/2026-06-26.md","filePath":"AI/daily/cn/2026-06/2026-06-26.md","lastUpdated":1783497398000}'),d={name:"ai/daily/cn/2026-06/2026-06-26.md"};function p(u,a,g,b,m,f){return t(),r("div",null,[...a[0]||(a[0]=[n(`<h1 align="center">2026-06-26 AI大事件</h1><h2 id="今日摘要" tabindex="-1"><strong>今日摘要</strong> <a class="header-anchor" href="#今日摘要" aria-label="Permalink to &quot;**今日摘要**&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>模型与产品更新：国内首个 AI 攻击测试套件发布、三体联名款 AI 穿戴设备正式开售、文心一言官网入口开启全面升级 🚀</span></span>
<span class="line"><span>前沿研究：快手 RaG 让推荐系统进入生成时代、WATER 算法攻克艺术字识别难题、IV-CoT 提升图像生成的结构感知 🧠</span></span>
<span class="line"><span>行业、政策与安全：近 400 家报纸联手起诉 OpenAI、WAIC UP! 打造人类最后思辨防线、2026 全球独角兽榜单总价值飙升 🔒</span></span>
<span class="line"><span>开源与开发者工具：no-mistakes：代码提交零失误、orca：多 Agent 协同工作站、headunit-revived：Android Auto 重生 🛠️</span></span>
<span class="line"><span>社媒与观点：Claude Fable 5 疑将解除封禁、跨模型与任务的 GitHub Copilot agentic harness 性能与效率评估、Generative AI Fizzle™：生成式AI泡沫正在缓慢消退 ( •̀ ω •́ )</span></span>
<span class="line"><span>今天的主线是模型、工具、研究与产业部署继续向可执行工作流收敛 (๑•̀ㅂ•́)و✧</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="模型与产品更新" tabindex="-1">模型与产品更新 <a class="header-anchor" href="#模型与产品更新" aria-label="Permalink to &quot;模型与产品更新&quot;">​</a></h2><h3 id="_1-国内首个-ai-攻击测试套件发布" tabindex="-1">1. 国内首个 AI 攻击测试套件发布 <a class="header-anchor" href="#_1-国内首个-ai-攻击测试套件发布" aria-label="Permalink to &quot;1. 国内首个 AI 攻击测试套件发布&quot;">​</a></h3><p>国内首个 AI 攻击测试套件发布。 斗象科技推出了 🔥 针对 AI 安全 的测试工具。企业应用现在( • ̀ω•́ )面临更多 越权风险。套件能检测 Agent 行为是否 👀 存在漏洞。目前已开放 社区版下载。这是保障大模型落地的 🛡️ 重要护栏。 来源：<a href="http://mp.weixin.qq.com/s?__biz=MjM5NjA0NjgyMA==&amp;mid=2651341222&amp;idx=1&amp;sn=c6e8c1255eb9b51ca8d59822442f95aa&amp;chksm=bce430c24625303db2ff736a9690c877279fc9592c6aecdaf1b5356eaa7c48bcd8d48b251652&amp;scene=0&amp;xtrack=1#rd" target="_blank" rel="noreferrer">社区版下载</a></p><p><img src="`+o+'" alt="AI资讯：技术人员正在使用测试套件拦截恶意攻击" loading="lazy"></p><h3 id="_2-三体联名款-ai-穿戴设备正式开售" tabindex="-1">2. 三体联名款 AI 穿戴设备正式开售 <a class="header-anchor" href="#_2-三体联名款-ai-穿戴设备正式开售" aria-label="Permalink to &quot;2. 三体联名款 AI 穿戴设备正式开售&quot;">​</a></h3><p>三体联名款 AI 穿戴设备正式开售。 光帆科技联动 💥 三体宇宙 推出全感设备。2026 年是《三体》问世(✧∀✧) 20 周年。新品采用超酷的 🚀“破晓橙”专属配色。快来 体验黑科技 赋予的想象空间。科幻小说里的终端终于 ✨ 照进了现实。 来源：<a href="https://www.qbitai.com/2026/06/438658.html" target="_blank" rel="noreferrer">体验黑科技</a></p><h3 id="_3-文心一言官网入口开启全面升级" tabindex="-1">3. 文心一言官网入口开启全面升级 <a class="header-anchor" href="#_3-文心一言官网入口开启全面升级" aria-label="Permalink to &quot;3. 文心一言官网入口开启全面升级&quot;">​</a></h3><p>文心一言官网入口开启全面升级。 用户数据将统一 🚀 迁移至 百度文心 网站。7 月 25 日前( • ̀ω•́ )务必完成 数据备份。新平台集成了更多 🔥 强大的 AI 生产力 工具。涵盖 PPT 生成及学术辅助等 多项功能。百度在大模型运营上 ✨ 迈出关键一步。 来源：<a href="https://www.aibase.com/zh/news/29164" target="_blank" rel="noreferrer">多项功能</a></p><h3 id="_4-openrouter-mcp-服务器发布" tabindex="-1">4. OpenRouter MCP 服务器发布 <a class="header-anchor" href="#_4-openrouter-mcp-服务器发布" aria-label="Permalink to &quot;4. OpenRouter MCP 服务器发布&quot;">​</a></h3><p>OpenRouter 推出 MCP 服务器，为编程智能体提供实时模型数据、基准排名、定价和文档查询。开发者通过一键安装（支持 Claude Code、Codex CLI、Cursor 等客户端），即可在编辑器内完成模型筛选、价格对比和测试推理，无需切换标签页。服务器整合 Artificial Analysis、Design Arena 及 OpenRouter 自身排名数据，例如推荐 GLM-5.2 作为性价比最佳的编码模型。工具集包括 models-list、model-get、model-endpoints、benchmarks 等，支持通过 chat-send 发送测试提示，比较不同模型（如 Claude Opus 4.8、G… 来源：<a href="https://openrouter.ai/blog/announcements/openrouter-mcp-server" target="_blank" rel="noreferrer">OpenRouter：Announcements（RSS）</a></p><h3 id="_5-codex-在-chatgpt-移动-app-正式可用" tabindex="-1">5. Codex 在 ChatGPT 移动 App 正式可用 <a class="header-anchor" href="#_5-codex-在-chatgpt-移动-app-正式可用" aria-label="Permalink to &quot;5. Codex 在 ChatGPT 移动 App 正式可用&quot;">​</a></h3><p>OpenAI 宣布 Codex 在 ChatGPT 移动应用中正式开放（GA），并新增一对一设备配对实现更安全的手机与电脑连接。移动端新增通知、目标、侧边聊天、文件预览及内联审阅评论功能。此前预览版已明确，用户可通过 ChatGPT 移动 App 启动新工作、审查输出、引导执行和批准下一步，而 Codex 实际继续在笔记本、Mac mini 或开发机上后台运行。 来源：<a href="https://x.com/OpenAIDevs/status/2070254532911882707" target="_blank" rel="noreferrer">X：OpenAI Developers (@OpenAIDevs)</a></p><h3 id="_6-runway-发布-agent-2-0" tabindex="-1">6. Runway 发布 Agent 2.0 <a class="header-anchor" href="#_6-runway-发布-agent-2-0" aria-label="Permalink to &quot;6. Runway 发布 Agent 2.0&quot;">​</a></h3><p>Runway 发布 Agent 2.0，帮助营销人员创建、测试和优化广告、视频及营销活动。品牌营销人员可在对话中开发活动概念、生成变体并自动本地化；绩效营销人员可上传创意并导入 Meta、YouTube、TikTok 或 Google 广告数据，由 Agent 分析后生成下一轮待测广告。社交媒体营销人员可一次性生成一周内容，自动裁切为 9:16、16:9、1:1 等格式；产品营销人员可借助 Agent 确定定位角度并构建活动资产。Agent 2.0 面向所有用户开放。 来源：<a href="https://runwayml.com/news/introducing-agent-2" target="_blank" rel="noreferrer">Runway：News（网页）</a></p><h3 id="_7-midjourney-v8-1-草稿模式新增随机风格功能" tabindex="-1">7. Midjourney V8.1 草稿模式新增随机风格功能 <a class="header-anchor" href="#_7-midjourney-v8-1-草稿模式新增随机风格功能" aria-label="Permalink to &quot;7. Midjourney V8.1 草稿模式新增随机风格功能&quot;">​</a></h3><p>Midjourney V8.1 的草稿模式（draft mode）添加了随机风格功能。用户在提示词中加入 <code>--sref random</code> 即可一键生成 24 张不同风格的图片。开启草稿模式可通过点击提示栏的 ⚡ 图标或添加 <code>--draft</code> 参数。 来源：<a href="https://updates.midjourney.com/random-styles-in-draft-mode" target="_blank" rel="noreferrer">Midjourney：Updates（RSS）</a></p><h3 id="_8-claude-code-v2-1-193-发布" tabindex="-1">8. Claude Code v2.1.193 发布 <a class="header-anchor" href="#_8-claude-code-v2-1-193-发布" aria-label="Permalink to &quot;8. Claude Code v2.1.193 发布&quot;">​</a></h3><p>Claude Code v2.1.193 新增 <code>autoMode.classifyAllShell</code> 设置，将全部 Bash/PowerShell 命令经自动模式分类器处理。自动模式拒绝原因现加入转录、拒绝提示及 <code>/permissions</code> 页面。新增 <code>claude_code.assistant_response</code> OpenTelemetry 日志事件（默认不记录，需设置 <code>OTEL_LOG_ASSISTANT_RESPONSES=1</code>）。Bash 模式支持实时文件路径自动补全；MCP 服务器需认证时显示启动提示。新增空闲后台 shell 命令自动内存压力回收（可禁用）。修复 <code>/model</code> UI 状态滞后、后台任务误取消、… 来源：<a href="https://github.com/anthropics/claude-code/releases/tag/v2.1.193" target="_blank" rel="noreferrer">Claude Code：GitHub Releases（RSS）</a></p><h3 id="_9-google-finance-全新-android-应用与投资组合功能上线" tabindex="-1">9. Google Finance 全新 Android 应用与投资组合功能上线 <a class="header-anchor" href="#_9-google-finance-全新-android-应用与投资组合功能上线" aria-label="Permalink to &quot;9. Google Finance 全新 Android 应用与投资组合功能上线&quot;">​</a></h3><p>本周，Google Finance 推出正式版 Android 应用，同步上线全球投资组合跟踪功能。用户可通过截图、CSV/PDF 上传或文字描述创建组合，并利用 AI 研究工具提问资产配置、固定收益影响等问题。新增市场情报简报功能：用户设定任务（如每日盘前简报），后台自动生成并推送至 Google 应用（Android/iOS）及网页端。Android 应用包含 watchlist、实时数据、金融新闻 feed、AI 研究工具及 AI 驱动的“关键时刻”解释股价波动。未来数月将把更多 web 功能（如财报电话、投资组合与任务）迁移至移动端，今年晚些推出 iOS 应用。 来源：<a href="https://blog.google/products-and-platforms/products/search/google-finance-updates-june-2026" target="_blank" rel="noreferrer">Google Blog：AI（RSS）</a></p><h3 id="_10-盈透证券-interactive-brokers-与-grok-集成-组合分析、情景建模与实时交易指令生成" tabindex="-1">10. 盈透证券（Interactive Brokers）与 Grok 集成：组合分析、情景建模与实时交易指令生成 <a class="header-anchor" href="#_10-盈透证券-interactive-brokers-与-grok-集成-组合分析、情景建模与实时交易指令生成" aria-label="Permalink to &quot;10. 盈透证券（Interactive Brokers）与 Grok 集成：组合分析、情景建模与实时交易指令生成&quot;">​</a></h3><p>盈透证券（Interactive Brokers）近日与 Grok 集成，用户可在几分钟内免费关联现有账户，无需注册新账户。通过自然语言与 Grok 对话，可完成组合收益分析（如股息与利息预测）、行业/地区/经济事件的风险敞口情景建模、市场趋势研究，并直接生成对冲订单等实时交易指令，实现从数据洞察到执行决策的一体化。 来源：<a href="https://x.ai/news/grok-interactive-brokers" target="_blank" rel="noreferrer">xAI：News（网页）</a></p><h2 id="前沿研究" tabindex="-1">前沿研究 <a class="header-anchor" href="#前沿研究" aria-label="Permalink to &quot;前沿研究&quot;">​</a></h2><h3 id="_1-快手-rag-让推荐系统进入生成时代" tabindex="-1">1. 快手 RaG 让推荐系统进入生成时代 <a class="header-anchor" href="#_1-快手-rag-让推荐系统进入生成时代" aria-label="Permalink to &quot;1. 快手 RaG 让推荐系统进入生成时代&quot;">​</a></h3><p>快手 RaG 让推荐系统进入生成时代。 系统不再只“找”视频而是 🚀 直接生产 视频。RaG 已在快手广告中(✧∀✧)覆盖 4 亿用户。它能将用户兴趣转化为 ✨ 具体的 拍摄指令。广告收入因此 大幅提升。推荐系统的边界正在 🛡️ 不断向外扩张。 来源：<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;mid=2651041184&amp;idx=3&amp;sn=6acf1bdd5b66fe4b491017767aef08a2" target="_blank" rel="noreferrer">大幅提升</a></p><p><img src="'+i+'" alt="AI资讯：RaG系统正在根据用户兴趣合成个性化视频" loading="lazy"></p><h3 id="_2-water-算法攻克艺术字识别难题" tabindex="-1">2. WATER 算法攻克艺术字识别难题 <a class="header-anchor" href="#_2-water-算法攻克艺术字识别难题" aria-label="Permalink to &quot;2. WATER 算法攻克艺术字识别难题&quot;">​</a></h3><p>WATER 算法攻克艺术字识别难题。 研究者构建了 200 万规模的 🚀 合成数据集。艺术字的高度定制化( • ̀ω•́ )曾是识别 痛点。WATERec 架构能灵活处理 🛡️ 各种复杂排版。识别准确率在榜单上 遥遥领先。 irregular 文本识别技术 ✨ 取得重大突破。 来源：<a href="https://huggingface.co/papers/2606.24484" target="_blank" rel="noreferrer">遥遥领先</a></p><p><img src="'+l+'" alt="AI资讯：WATER模型精准识别街头霓虹灯艺术字体" loading="lazy"></p><h3 id="_3-iv-cot-提升图像生成的结构感知" tabindex="-1">3. IV-CoT 提升图像生成的结构感知 <a class="header-anchor" href="#_3-iv-cot-提升图像生成的结构感知" aria-label="Permalink to &quot;3. IV-CoT 提升图像生成的结构感知&quot;">​</a></h3><p>IV-CoT 提升图像生成的结构感知。 该框架通过隐式 🚀 视觉思维链 拆解任务。它先规划结构再渲染(✧∀✧)具体的 外观细节。无需中间解码即可实现 ✨ 精准的布局控制。点击 查看技术论文。物体计数和空间关系 🛡️ 变得更加准确。 来源：<a href="https://huggingface.co/papers/2606.24849" target="_blank" rel="noreferrer">查看技术论文</a></p><p><img src="'+s+'" alt="AI资讯：IV-CoT模型根据草图生成精细的室内设计图" loading="lazy"></p><h3 id="_4-causal-rcm-加速实时视频生成" tabindex="-1">4. Causal-rCM 加速实时视频生成 <a class="header-anchor" href="#_4-causal-rcm-加速实时视频生成" aria-label="Permalink to &quot;4. Causal-rCM 加速实时视频生成&quot;">​</a></h3><p>Causal-rCM 加速实时视频生成。 自回归视频扩散模型 🚀 实现了 秒级成像。该方案显著提升了( • ̀ω•́ )交互式 世界模型 性能。训练收敛速度比 ✨ 传统方法快 10 倍。更多实验数据见 研究报告。物理 AI 的实时交互 🛡️ 从此成为可能。 来源：<a href="https://huggingface.co/papers/2606.25473" target="_blank" rel="noreferrer">研究报告</a></p><p><img src="'+h+'" alt="AI资讯：Causal-rCM算法在毫秒内渲染出流动的水波视频" loading="lazy"></p><h3 id="_5-agent-原生存储系统性能大测评" tabindex="-1">5. Agent 原生存储系统性能大测评 <a class="header-anchor" href="#_5-agent-原生存储系统性能大测评" aria-label="Permalink to &quot;5. Agent 原生存储系统性能大测评&quot;">​</a></h3><p>Agent 原生存储系统性能大测评。 存储系统已进化为 🚀 复杂的 数据管理 框架。研究对 12 种主流(✧∀✧)存储进行了 深度横评。发现局部维护比 ✨ 全局重组更具性价比。开源地址可见 Github 仓库。这是构建强 Agent 🛡️ 不可或缺的基础。 来源：<a href="https://huggingface.co/papers/2606.24775" target="_blank" rel="noreferrer">Github 仓库</a></p><p><img src="'+c+'" alt="AI资讯：研究员对比不同AI代理存储模块的响应速度" loading="lazy"></p><h3 id="_6-赫库兰尼姆古卷首次被完整虚拟解读" tabindex="-1">6. 赫库兰尼姆古卷首次被完整虚拟解读 <a class="header-anchor" href="#_6-赫库兰尼姆古卷首次被完整虚拟解读" aria-label="Permalink to &quot;6. 赫库兰尼姆古卷首次被完整虚拟解读&quot;">​</a></h3><p>研究人员利用高分辨率 X 射线显微断层扫描和机器学习，在未物理展开的情况下完整虚拟展开并读取了赫库兰尼姆古卷 PHerc.1667（Scroll4）。这是首卷被从头到尾连续读取的纸莎草卷，内容为斯多葛哲学论著，提及克里西普斯的侄子 Aristocreon。第二卷 PHerc.Paris4 通过更高分辨率成像使墨水在三维数据中直接可见，独立确认了 2023 年大奖赛的解读。第三卷 PHerc.139 确定标题和作者为菲洛德穆《论诸神》第八卷。所有数据与代码已公开。 来源：<a href="https://scrollprize.org/firstscroll" target="_blank" rel="noreferrer">Hacker News 热门（buzzing.cc 中文翻译）</a></p><h3 id="_7-ibm-首度推出亚纳米级芯片技术" tabindex="-1">7. IBM 首度推出亚纳米级芯片技术 <a class="header-anchor" href="#_7-ibm-首度推出亚纳米级芯片技术" aria-label="Permalink to &quot;7. IBM 首度推出亚纳米级芯片技术&quot;">​</a></h3><p>IBM 于 2026 年 6 月 25 日发布全球首款亚纳米级芯片技术，采用 0.7 nm（7 埃米）节点与全新三维纳米堆叠（nanostack）架构。指甲盖大小的芯片集成近 1000 亿个晶体管，密度约为 IBM 2021 年 2 nm 芯片的两倍。相比 2 nm 芯片，性能最高提升 50%，能效最高提升 70%。纳米堆叠架构还实现 SRAM 面积缩减 40%，有助于支撑先进 AI 工作负载的高带宽需求。该技术已在 VLSI 2026 会议上验证，IBM 预计 5 年内量产。 来源：<a href="https://newsroom.ibm.com/2026-06-25-ibm-debuts-worlds-first-sub-1-nanometer-chip-technology" target="_blank" rel="noreferrer">Hacker News 热门（buzzing.cc 中文翻译）</a></p><h3 id="_8-openai-内部报告-智能体-codex-如何改变工作" tabindex="-1">8. OpenAI 内部报告：智能体 Codex 如何改变工作 <a class="header-anchor" href="#_8-openai-内部报告-智能体-codex-如何改变工作" aria-label="Permalink to &quot;8. OpenAI 内部报告：智能体 Codex 如何改变工作&quot;">​</a></h3><p>OpenAI 在 2025 年 8 月至 2026 年 6 月间观察到，智能体产品 Codex 取代 ChatGPT 成为主要工作工具，各部门输出 token 中 Codex 占比从不足 10%升至 99.8%。80.6%个体用户曾发起预计等效人类工作时间超 30 分钟的请求，70.2%超 1 小时，25.6%超 8 小时；99 百分位用户每日生成超 60 小时 agent turns。非开发者用户增长迅猛：个体用户增长 137 倍，组织用户增长 189 倍。Legal、Finance、Recruiting 部门在 2026 年 4 月前后跨过 Codex 使用过半拐点，平均每位律师或招聘人员超 85%输出 token 来自 Codex。 来源：<a href="https://openai.com/index/how-agents-are-transforming-work" target="_blank" rel="noreferrer">OpenAI：官网动态（RSS · 排除企业/客户案例）</a></p><h3 id="_9-用线性弹性缓存优化云经济" tabindex="-1">9. 用线性弹性缓存优化云经济 <a class="header-anchor" href="#_9-用线性弹性缓存优化云经济" aria-label="Permalink to &quot;9. 用线性弹性缓存优化云经济&quot;">​</a></h3><p>Google Research 与 Google Cloud 提出线性弹性缓存，将缓存管理转为线性成本优化问题，动态调整大小以最小化总拥有成本。为每条数据引入“滑雪租赁”决策框架，在租用内存（持续付费）与购买缺失（缓存未命中惩罚）间选择，并用轻量级机器学习实时优化内存占用与缺失率权衡。无服务器云场景下（每 GiB 内存每天 $3），该技术可在不牺牲性能的同时显著降本。论文发表于 CIDR。 来源：<a href="https://research.google/blog/optimizing-cloud-economics-with-linear-elastic-caching" target="_blank" rel="noreferrer">Google Research：Blog（网页）</a></p><h2 id="行业、政策与安全" tabindex="-1">行业、政策与安全 <a class="header-anchor" href="#行业、政策与安全" aria-label="Permalink to &quot;行业、政策与安全&quot;">​</a></h2><h3 id="_1-近-400-家报纸联手起诉-openai" tabindex="-1">1. 近 400 家报纸联手起诉 OpenAI <a class="header-anchor" href="#_1-近-400-家报纸联手起诉-openai" aria-label="Permalink to &quot;1. 近 400 家报纸联手起诉 OpenAI&quot;">​</a></h3><p>近 400 家报纸联手起诉 OpenAI。 出版商指控科技巨头 🚀 系统性 侵犯版权。他们认为 AI 训练(✧∀✧)剥夺了 原创劳动 价值。诉讼涉及 ChatGPT 及微软 Copilot 产品的底层。阅读 诉讼详情。地方新闻机构的 🛡️ 生存环境面临严峻挑战。 来源：<a href="https://www.aibase.com/zh/news/29171" target="_blank" rel="noreferrer">诉讼详情</a></p><h3 id="_2-waic-up-打造人类最后思辨防线" tabindex="-1">2. WAIC UP! 打造人类最后思辨防线 <a class="header-anchor" href="#_2-waic-up-打造人类最后思辨防线" aria-label="Permalink to &quot;2. WAIC UP! 打造人类最后思辨防线&quot;">​</a></h3><p>WAIC UP! 打造人类最后思辨防线。 AI 行业正处于(✧∀✧) 集体眩晕 的参数竞争中。该刊物试图追问 🚀 技术对人类的 深层意义。60 余位跨界先锋 ✨ 发表了独到见解。关注 深度思想。在智能伙伴时代保留 🔥 一份稀缺的清醒。 来源：<a href="https://www.qbitai.com/2026/06/438364.html" target="_blank" rel="noreferrer">深度思想</a></p><h3 id="_3-2026-全球独角兽榜单总价值飙升" tabindex="-1">3. 2026 全球独角兽榜单总价值飙升 <a class="header-anchor" href="#_3-2026-全球独角兽榜单总价值飙升" aria-label="Permalink to &quot;3. 2026 全球独角兽榜单总价值飙升&quot;">​</a></h3><p>2026 全球独角兽榜单总价值飙升。 AI 领域独角兽 🚀 数量较去年 激增 87 家。Anthropic 以 6.6 万亿估值( • ̀ω•́ )夺得 全球第一。中国以 381 家企业 ✨ 稳居全球第二。查看 完整榜单。资本正以前所未有的 🔥 力度重塑科技重心。 来源：<a href="https://www.aibase.com/zh/news/29163" target="_blank" rel="noreferrer">完整榜单</a></p><h3 id="_4-谷歌-ai-天团核心人才集体出走" tabindex="-1">4. 谷歌 AI 天团核心人才集体出走 <a class="header-anchor" href="#_4-谷歌-ai-天团核心人才集体出走" aria-label="Permalink to &quot;4. 谷歌 AI 天团核心人才集体出走&quot;">​</a></h3><p>谷歌 AI 天团核心人才集体出走。 多位 Gemini 开发功臣 🚀 投奔竞争对手 Anthropic。包括 AlphaFold 项目的(✧∀✧) 诺奖级总监 约翰。人才流失使谷歌面临 🛡️ 极其严峻的挑战。阅读 行业动态。初创独角兽的 🔥 股权承诺成为最强筹码。 来源：<a href="https://www.aibase.com/zh/news/29139" target="_blank" rel="noreferrer">行业动态</a></p><h3 id="_5-momenta-率先冲刺港股物理-ai-第一股" tabindex="-1">5. Momenta 率先冲刺港股物理 AI 第一股 <a class="header-anchor" href="#_5-momenta-率先冲刺港股物理-ai-第一股" aria-label="Permalink to &quot;5. Momenta 率先冲刺港股物理 AI 第一股&quot;">​</a></h3><p>Momenta 率先冲刺港股物理 AI 第一股。 自动驾驶领头羊 🚀 正式启动 IPO 进程。其 R7 世界模型已在 ✨ 量产车上实现落地。许可收入三年( • ̀ω•́ )竟然 增长了 42 倍。关注 上市进展。世界模型成为物理 AI 竞争的 🛡️ 核心战场。 来源：<a href="https://www.qbitai.com/2026/06/438179.html" target="_blank" rel="noreferrer">上市进展</a></p><h3 id="_6-anthropic-称阿里巴巴非法获取了-claude-ai-模型的功能" tabindex="-1">6. Anthropic 称阿里巴巴非法获取了 Claude AI 模型的功能 <a class="header-anchor" href="#_6-anthropic-称阿里巴巴非法获取了-claude-ai-模型的功能" aria-label="Permalink to &quot;6. Anthropic 称阿里巴巴非法获取了 Claude AI 模型的功能&quot;">​</a></h3><p>Anthropic 指控阿里巴巴未经授权提取了其 Claude AI 模型的能力。该指控基于 Anthropic 的调查，认为阿里巴巴通过逆向工程或其他手段复制了 Claude 的核心技术。目前阿里巴巴尚未公开回应。 来源：<a href="https://www.reuters.com/world/china/anthropic-says-alibaba-illicitly-extracted-claude-ai-model-capabilities-2026-06-24" target="_blank" rel="noreferrer">Hacker News 热门（buzzing.cc 中文翻译）</a></p><h3 id="_7-suno-推出-spark-支持下一代独立艺术家" tabindex="-1">7. Suno 推出 Spark：支持下一代独立艺术家 <a class="header-anchor" href="#_7-suno-推出-spark-支持下一代独立艺术家" aria-label="Permalink to &quot;7. Suno 推出 Spark：支持下一代独立艺术家&quot;">​</a></h3><p>Suno 宣布启动 <strong>Spark</strong> 孵化器项目，面向年满 18 岁的未签约独立歌手、词曲作者和制作人。入选者将获得创作资助和额外营销经费，受邀与知名艺术家共同参与写歌营，并有机会为 Suno 正在构建的新功能提供反馈。艺术家保留其作品的创意控制权和商业权利。即日起开放申请。 来源：<a href="https://suno.com/blog/introducing-spark" target="_blank" rel="noreferrer">Suno：Blog（网页）</a></p><h2 id="开源与开发者工具" tabindex="-1">开源与开发者工具 <a class="header-anchor" href="#开源与开发者工具" aria-label="Permalink to &quot;开源与开发者工具&quot;">​</a></h2><h3 id="_1-no-mistakes-代码提交零失误" tabindex="-1">1. no-mistakes：代码提交零失误 <a class="header-anchor" href="#_1-no-mistakes-代码提交零失误" aria-label="Permalink to &quot;1. no-mistakes：代码提交零失误&quot;">​</a></h3><p>no-mistakes：代码提交零失误。 这是 Go 语言编写的 🚀 git 增强工具。帮助开发者在 push 前(✧∀✧)检查 所有隐患。项目今日斩获 ⭐110 Star。再也不用担心 ✨ 误删生产环境分支。 来源：<a href="https://github.com/kunchenguid/no-mistakes" target="_blank" rel="noreferrer">Star</a></p><h3 id="_2-orca-多-agent-协同工作站" tabindex="-1">2. orca：多 Agent 协同工作站 <a class="header-anchor" href="#_2-orca-多-agent-协同工作站" aria-label="Permalink to &quot;2. orca：多 Agent 协同工作站&quot;">​</a></h3><p>orca：多 Agent 协同工作站。 Orca 是运行并行 🚀 Agent 舰队 的专用 ADE。支持在移动端和桌面端( • ̀ω•́ )运行 编程代理。累计获得 ⭐6.7k Star。让每个人都能 ✨ 拥有自己的 AI 员工。 来源：<a href="https://github.com/stablyai/orca" target="_blank" rel="noreferrer">Star</a></p><h3 id="_3-headunit-revived-android-auto-重生" tabindex="-1">3. headunit-revived：Android Auto 重生 <a class="header-anchor" href="#_3-headunit-revived-android-auto-重生" aria-label="Permalink to &quot;3. headunit-revived：Android Auto 重生&quot;">​</a></h3><p>headunit-revived：Android Auto 重生。 开源的 🚀 车载 显示应用 已获得广泛关注。支持通过 Kotlin 重新(✧∀✧)驱动 旧款车机。今日新增 ⭐41 Star。让老车也能 ✨ 焕发 AI 时代的生机。 来源：<a href="https://github.com/andreknieriem/headunit-revived" target="_blank" rel="noreferrer">Star</a></p><h2 id="社媒与观点" tabindex="-1">社媒与观点 <a class="header-anchor" href="#社媒与观点" aria-label="Permalink to &quot;社媒与观点&quot;">​</a></h2><h3 id="_1-claude-fable-5-疑将解除封禁" tabindex="-1">1. Claude Fable 5 疑将解除封禁 <a class="header-anchor" href="#_1-claude-fable-5-疑将解除封禁" aria-label="Permalink to &quot;1. Claude Fable 5 疑将解除封禁&quot;">​</a></h3><p>Claude Fable 5 疑将解除封禁。 因被发现 🚀 绕过分类器 而被迫下线 13 天。预测市场认为其( • ̀ω•́ )在 7 月前 回归概率 57%。开发者们正焦急 等待上线。这也引发了对 🛡️ 闭源模型掌控权的争议。 来源：<a href="https://www.reddit.com/r/artificial/comments/1uf5pzu/claude_fable_5_may_return_today_after_13day/" target="_blank" rel="noreferrer">等待上线</a></p><h3 id="_2-跨模型与任务的-github-copilot-agentic-harness-性能与效率评估" tabindex="-1">2. 跨模型与任务的 GitHub Copilot agentic harness 性能与效率评估 <a class="header-anchor" href="#_2-跨模型与任务的-github-copilot-agentic-harness-性能与效率评估" aria-label="Permalink to &quot;2. 跨模型与任务的 GitHub Copilot agentic harness 性能与效率评估&quot;">​</a></h3><p>GitHub Copilot agentic harness 在多个基准测试中表现强劲，同时具备领先的 token 效率，并支持在 20 多个模型间灵活选择。 来源：<a href="https://github.blog/ai-and-ml/github-copilot/evaluating-performance-and-efficiency-of-the-github-copilot-agentic-harness-across-models-and-tasks" target="_blank" rel="noreferrer">GitHub Blog</a></p><h3 id="_3-generative-ai-fizzletm-生成式-ai-泡沫正在缓慢消退" tabindex="-1">3. Generative AI Fizzle™：生成式 AI 泡沫正在缓慢消退 <a class="header-anchor" href="#_3-generative-ai-fizzletm-生成式-ai-泡沫正在缓慢消退" aria-label="Permalink to &quot;3. Generative AI Fizzle™：生成式 AI 泡沫正在缓慢消退&quot;">​</a></h3><p>Gary Marcus 昨日提出新术语 Generative AI Fizzle™，认为生成式 AI 行业估值过高，投资者对 hype 与利润的落差失去热情。LLM 已商品化，价格战激烈，提供商盈利艰难。昨日一款新的中国开源模型发布，可能进一步冲击美国 LLM 公司。多数 AI 股票本月显著下跌，泡沫可能不会突然破裂，而是缓慢消退。 来源：<a href="https://garymarcus.substack.com/p/the-generative-ai-fizzle" target="_blank" rel="noreferrer">Gary Marcus：The Road to AI We Can Trust（RSS）</a></p><h3 id="快讯" tabindex="-1">快讯 <a class="header-anchor" href="#快讯" aria-label="Permalink to &quot;快讯&quot;">​</a></h3><ul><li><strong>AI 视频创业的现实经济账</strong>：AI 视频创业的现实经济账。 博主发现 Seedance 2.0 抽卡 🚀 成本极高。一分钟 4K 广告片(✧∀✧)可能要 花费 700 块。但每天给字节带来的 ✨ 收益却非常惊人。阅读 创业感悟。贵的东西在需求方眼里 🛡️ 反而是便宜的。 来源：<a href="https://m.okjike.com/originalPosts/6a3cd8fa3d621d7862ec5b51" target="_blank" rel="noreferrer">创业感悟</a></li><li><strong>多数主流 AI 聊天机器人政治立场偏左，“反觉醒”模型也不例外</strong>：华盛顿邮报调查显示，多数主流 AI 聊天机器人在政治问题上明显偏左。OpenAI GPT-5.5 在 80%回答中仅呈现左派论据；DeepSeek V4 Pro 为 70%；Anthropic Claude Opus 4.8 有 43%纯左、57%给出双方观点。xAI 的 Grok 4.3 左倾回答仍多于右倾。右翼平台 Gab 的 Arya 左倾回答是右倾的 12 倍。Google Gemini 3.1 Pro 是例外，93%回答同时呈现双方立场。特朗普推动的“反觉醒”AI 未能改变这一格局。 来源：<a href="https://the-decoder.com/most-major-ai-chatbots-still-lean-left-on-political-questions-even-anti-woke-models-are-no-exception" target="_blank" rel="noreferrer">The Decoder：AI News（RSS）</a></li><li><strong>OLMo Hybrid vs Transformer：混合模型在实义词上优势明显，但重复短语上几无优势</strong>：通过对比 7B 参数的 OLMo 3（Transformer）与 OLMo Hybrid（混合架构），实验发现混合模型在大多数 token 上预测损失更低：对名词、动词、形容词等实义词优势明显（loss gap 约 0.04），功能词上 gap 约 0.02，且在需上下文推理的代词指代上更好。但在重复出现的 n-gram 和闭合括号（如<code>}</code>）上，混合模型的优势几乎消失，Transformer 凭借注意力机制更擅长从输入中直接检索精确信息。 来源：<a href="https://huggingface.co/blog/allenai/hybrid-token-prediction" target="_blank" rel="noreferrer">Hugging Face：Blog（RSS）</a></li><li><strong>Meta 隐私感知基础设施的资产分类：混合模式将 LLM 蒸馏为确定性规则</strong>：Meta 在 Privacy-Aware Infrastructure (PAI) 的资产分类中采用混合模式：先构建含代码、血缘、语义标注的上下文证据，再调用 LLM 处理歧义、冷启动和新颖资产；人工审核标签与模型推荐严格隔离。LLM 不直接做生产决策，其稳定行为被蒸馏为版本化确定性规则用于生产执行，LLM 角色随规则积累逐步缩小。核心原则：上下文比提示词更重要、解耦评估与优化、将稳定行为规则化。 来源：<a href="https://engineering.fb.com/2026/06/25/security/privacy-aware-infrastructure-in-the-ai-native-era-an-asset-classification-case-study" target="_blank" rel="noreferrer">Meta Engineering Blog（RSS）</a></li><li><strong>Sail Research 构建集群感知编排，加速异步推理</strong>：推理市场是软件中最大的市场。AI 工作负载正从同步聊天转向异步、多轮智能体，运行时长可达数小时。Sail Research 为此构建了集群感知（fleet‑aware）编排系统，以最大化每美元推理支出的吞吐量。 来源：<a href="https://www.tomtunguz.com/sail-inference-queue" target="_blank" rel="noreferrer">Tomer Tunguz 博客（VC 分析）</a></li></ul><h2 id="今日总结与启示" tabindex="-1">今日总结与启示 <a class="header-anchor" href="#今日总结与启示" aria-label="Permalink to &quot;今日总结与启示&quot;">​</a></h2><ul><li><strong>模型与产品更新继续升温。</strong> 国内首个 AI 攻击测试套件发布 是今天最值得跟进的信号之一，后续要看能力是否能稳定进入真实工作流 🚀。</li><li><strong>前沿研究继续升温。</strong> 快手 RaG 让推荐系统进入生成时代 是今天最值得跟进的信号之一，后续要看能力是否能稳定进入真实工作流 🧠。</li><li><strong>行业、政策与安全继续升温。</strong> 近 400 家报纸联手起诉 OpenAI 是今天最值得跟进的信号之一，后续要看能力是否能稳定进入真实工作流 🔒。</li><li><strong>开源与开发者工具继续升温。</strong> no-mistakes：代码提交零失误 是今天最值得跟进的信号之一，后续要看能力是否能稳定进入真实工作流 🛠️。</li><li><strong>社媒与观点继续升温。</strong> Claude Fable 5 疑将解除封禁 是今天最值得跟进的信号之一，后续要看能力是否能稳定进入真实工作流 ( •̀ ω •́ )。</li></ul>',82)])])}const k=e(d,[["render",p]]);export{A as __pageData,k as default};
